CREATE TABLE IF NOT EXISTS admins(id SERIAL PRIMARY KEY,email VARCHAR(190) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'super_admin',created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS settings(key VARCHAR(100) PRIMARY KEY,value TEXT,updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS categories(id SERIAL PRIMARY KEY,parent_id INT REFERENCES categories(id) ON DELETE CASCADE,name VARCHAR(255) NOT NULL,slug VARCHAR(255) UNIQUE NOT NULL,section VARCHAR(40) NOT NULL DEFAULT 'science',active BOOLEAN DEFAULT TRUE,sort_order INT DEFAULT 0,description TEXT,updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS authors(id SERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,full_name VARCHAR(500),birth_year VARCHAR(100),death_year VARCHAR(100),location VARCHAR(255),biography TEXT,teachers TEXT,students TEXT,works TEXT,aliases TEXT,photo_path TEXT,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS books(id SERIAL PRIMARY KEY,title VARCHAR(500) NOT NULL,slug VARCHAR(500),author_id INT REFERENCES authors(id) ON DELETE SET NULL,language_code VARCHAR(20) DEFAULT 'fa',translator VARCHAR(255),pages INT,volumes INT DEFAULT 1,publication_year VARCHAR(100),publisher VARCHAR(255),source_name VARCHAR(255),source_url TEXT,description TEXT,full_description TEXT,keywords TEXT,cover_path TEXT,status VARCHAR(30) DEFAULT 'published',featured BOOLEAN DEFAULT FALSE,featured_order INT DEFAULT 0,admin_order INT DEFAULT 0,is_my_book BOOLEAN DEFAULT FALSE,views BIGINT DEFAULT 0,downloads BIGINT DEFAULT 0,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS book_volumes(id SERIAL PRIMARY KEY,book_id INT REFERENCES books(id) ON DELETE CASCADE,volume_no INT NOT NULL,volume_title VARCHAR(500),pages INT,file_path TEXT,external_url TEXT,source_name VARCHAR(255),downloads BIGINT DEFAULT 0,created_at TIMESTAMP DEFAULT NOW(),UNIQUE(book_id,volume_no));
CREATE TABLE IF NOT EXISTS book_categories(book_id INT REFERENCES books(id) ON DELETE CASCADE,category_id INT REFERENCES categories(id) ON DELETE CASCADE,PRIMARY KEY(book_id,category_id));
CREATE TABLE IF NOT EXISTS book_relations(book_id INT REFERENCES books(id) ON DELETE CASCADE,related_book_id INT REFERENCES books(id) ON DELETE CASCADE,relation_type VARCHAR(50) NOT NULL,PRIMARY KEY(book_id,related_book_id,relation_type));
CREATE TABLE IF NOT EXISTS submissions(id SERIAL PRIMARY KEY,submitter_name VARCHAR(255),email VARCHAR(255),phone VARCHAR(100),book_title VARCHAR(500),author_name VARCHAR(500),description TEXT,language_code VARCHAR(20),publication_year VARCHAR(100),file_path TEXT,cover_path TEXT,external_url TEXT,status VARCHAR(30) DEFAULT 'pending',admin_note TEXT,tracking_token VARCHAR(100) UNIQUE,created_at TIMESTAMP DEFAULT NOW(),updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS feedback(id SERIAL PRIMARY KEY,name VARCHAR(255),email VARCHAR(255),message TEXT NOT NULL,approved BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS featured_books(book_id INT PRIMARY KEY REFERENCES books(id) ON DELETE CASCADE,sort_order INT DEFAULT 0,active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS activity_logs(id BIGSERIAL PRIMARY KEY,admin_id INT REFERENCES admins(id) ON DELETE SET NULL,action VARCHAR(100),entity_type VARCHAR(100),entity_id INT,details TEXT,created_at TIMESTAMP DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_books_status ON books(status); CREATE INDEX IF NOT EXISTS idx_books_views ON books(views DESC); CREATE INDEX IF NOT EXISTS idx_books_updated ON books(updated_at DESC); CREATE INDEX IF NOT EXISTS idx_categories_parent ON categories(parent_id); CREATE INDEX IF NOT EXISTS idx_books_title ON books(title);
